CREATE TEMPORARY TABLE rules_v006_preflight (ok TINYINT NOT NULL CHECK (ok = 1));
INSERT INTO rules_v006_preflight (ok)
SELECT CASE WHEN CAST(DATABASE() AS BINARY) = _binary'dnd_tool_rules'
    AND (FIND_IN_SET('STRICT_TRANS_TABLES', @@SESSION.sql_mode) > 0 OR FIND_IN_SET('STRICT_ALL_TABLES', @@SESSION.sql_mode) > 0)
    AND (SELECT COUNT(*) FROM rule_schema_meta) = 5
    AND (SELECT COUNT(*) FROM rule_schema_meta WHERE (schema_version = 1 AND CAST(script_name AS BINARY) = _binary'V001__rule-source-schema.sql' AND CAST(script_sha256 AS BINARY) = _binary'003916bc758315351e46f177fec10eb70f2b1275a524d270c6eb89a602cd130e') OR (schema_version = 2 AND CAST(script_name AS BINARY) = _binary'V002__tool-catalog.sql' AND CAST(script_sha256 AS BINARY) = _binary'2a5a8a67ebef60754ff9ca572d651878558ccc56ed2bfd311ce811ef42082c40') OR (schema_version = 3 AND CAST(script_name AS BINARY) = _binary'V003__schema2-source-ledger.sql' AND CAST(script_sha256 AS BINARY) = _binary'4166a7f4b4d8670a8300c4129ce566e177b824dda24c58ee3d208f9880048cdf') OR (schema_version = 4 AND CAST(script_name AS BINARY) = _binary'V004__schema2-character-grant-source.sql' AND CAST(script_sha256 AS BINARY) = _binary'9578db2143bfb14eb077e403d5395bb3089a7ab6e54f6926f42b7dbcac4e9269') OR (schema_version = 5 AND CAST(script_name AS BINARY) = _binary'V005__schema2-advancement-source.sql' AND CAST(script_sha256 AS BINARY) = _binary'2dfdecf8cb30fcc71f7e011550ce3b32334340aab5ff546f4e71e53e13147e5c')) = 5
    AND (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name IN ('rule_schema2_check')) = 0
    THEN 1 ELSE NULL END;
DROP TEMPORARY TABLE rules_v006_preflight;

CREATE TABLE rule_schema2_check (
    artifact_module_key VARBINARY(64) NOT NULL,
    release_version VARBINARY(64) NOT NULL,
    author_index INT NOT NULL,
    module_key VARBINARY(64) NOT NULL,
    rule_type VARBINARY(32) NOT NULL,
    rule_key VARBINARY(128) NOT NULL,
    display_name VARCHAR(120) NOT NULL,
    description VARCHAR(1000) NOT NULL,
    source_page INT NOT NULL,
    algorithm VARBINARY(128) NOT NULL,
    author_note VARCHAR(1000) NULL,
    PRIMARY KEY (artifact_module_key, release_version, author_index),
    UNIQUE KEY uq_s2_src_check (artifact_module_key, release_version, module_key, rule_type, rule_key),
    CONSTRAINT fk_s2_src_check_artifact FOREIGN KEY (artifact_module_key, release_version) REFERENCES rule_schema2_artifact (module_key, release_version) ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT ck_s2_src_check_identity CHECK (author_index BETWEEN 0 AND 255 AND module_key = artifact_module_key AND rule_type = _binary'adventure.check' AND REGEXP_LIKE(CONVERT(rule_key USING latin1), '^check[.][a-z][a-z0-9_]*([.][a-z0-9_]+)*$', 'c') AND NOT REGEXP_LIKE(CONVERT(rule_key USING latin1), '[^a-z0-9_.]', 'c')),
    CONSTRAINT ck_s2_src_check_profile CHECK (source_page = 77 AND algorithm = _binary'SRD_2014_ABILITY_CHECK_V1'),
    CONSTRAINT ck_s2_src_check_name CHECK (CHAR_LENGTH(display_name) BETWEEN 1 AND 120 AND NOT REGEXP_LIKE(display_name, '[[:cntrl:]]') AND REGEXP_LIKE(display_name, '[^[:space:]]')),
    CONSTRAINT ck_s2_src_check_description CHECK (CHAR_LENGTH(description) BETWEEN 1 AND 1000 AND NOT REGEXP_LIKE(description, '[[:cntrl:]]') AND REGEXP_LIKE(description, '[^[:space:]]')),
    CONSTRAINT ck_s2_src_check_note CHECK (author_note IS NULL OR (CHAR_LENGTH(author_note) BETWEEN 1 AND 1000 AND NOT REGEXP_LIKE(author_note, '[[:cntrl:]]') AND REGEXP_LIKE(author_note, '[^[:space:]]')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

ALTER TABLE rule_schema2_advancement_change DROP CHECK ck_s2_src_advancement_change_1;
ALTER TABLE rule_schema2_advancement_change ADD CONSTRAINT ck_s2_src_advancement_change_1 CHECK ((rule_type = _binary'character.class_progression' AND REGEXP_LIKE(CONVERT(rule_key USING latin1), '^progression[.][a-z][a-z0-9_]*([.][a-z0-9_]+)*$', 'c') AND NOT REGEXP_LIKE(CONVERT(rule_key USING latin1), '[^a-z0-9_.]', 'c')) OR (rule_type = _binary'character.resource' AND REGEXP_LIKE(CONVERT(rule_key USING latin1), '^resource[.][a-z][a-z0-9_]*([.][a-z0-9_]+)*$', 'c') AND NOT REGEXP_LIKE(CONVERT(rule_key USING latin1), '[^a-z0-9_.]', 'c')) OR (rule_type = _binary'character.subclass' AND REGEXP_LIKE(CONVERT(rule_key USING latin1), '^subclass[.][a-z][a-z0-9_]*([.][a-z0-9_]+)*$', 'c') AND NOT REGEXP_LIKE(CONVERT(rule_key USING latin1), '[^a-z0-9_.]', 'c')) OR (rule_type = _binary'character.feature' AND REGEXP_LIKE(CONVERT(rule_key USING latin1), '^feature[.][a-z][a-z0-9_]*([.][a-z0-9_]+)*$', 'c') AND NOT REGEXP_LIKE(CONVERT(rule_key USING latin1), '[^a-z0-9_.]', 'c')) OR (rule_type = _binary'character.feat' AND REGEXP_LIKE(CONVERT(rule_key USING latin1), '^feat[.][a-z][a-z0-9_]*([.][a-z0-9_]+)*$', 'c') AND NOT REGEXP_LIKE(CONVERT(rule_key USING latin1), '[^a-z0-9_.]', 'c')) OR (rule_type = _binary'character.proficiency' AND REGEXP_LIKE(CONVERT(rule_key USING latin1), '^proficiency[.][a-z][a-z0-9_]*([.][a-z0-9_]+)*$', 'c') AND NOT REGEXP_LIKE(CONVERT(rule_key USING latin1), '[^a-z0-9_.]', 'c')) OR (rule_type = _binary'catalog.proficiency_set' AND REGEXP_LIKE(CONVERT(rule_key USING latin1), '^proficiency_set[.][a-z][a-z0-9_]*([.][a-z0-9_]+)*$', 'c') AND NOT REGEXP_LIKE(CONVERT(rule_key USING latin1), '[^a-z0-9_.]', 'c')) OR (rule_type = _binary'adventure.rest' AND REGEXP_LIKE(CONVERT(rule_key USING latin1), '^rest[.][a-z][a-z0-9_]*([.][a-z0-9_]+)*$', 'c')) OR (rule_type = _binary'adventure.check' AND REGEXP_LIKE(CONVERT(rule_key USING latin1), '^check[.][a-z][a-z0-9_]*([.][a-z0-9_]+)*$', 'c')));

ALTER TABLE rule_schema2_advancement_change DROP CHECK ck_s2_src_advancement_change_2;
ALTER TABLE rule_schema2_advancement_change ADD CONSTRAINT ck_s2_src_advancement_change_2 CHECK ((target_kind = _binary'rule' AND collection_key IS NULL AND module_key IS NULL AND entry_key IS NULL AND ((rule_type = _binary'character.class_progression' AND field_key IN (_binary'display_name', _binary'author_note', _binary'enabled', _binary'description', _binary'source_page', _binary'owner_class', _binary'hit_die_sides', _binary'proficiency_bonus_profile', _binary'supported_maximum_level', _binary'advancement_scope', _binary'multiclass_prerequisite')) OR (rule_type = _binary'character.resource' AND field_key IN (_binary'display_name', _binary'author_note', _binary'enabled', _binary'description', _binary'source_page', _binary'owner_class', _binary'maximum_profile', _binary'recovery_profile', _binary'execution_mode')) OR (rule_type = _binary'character.subclass' AND field_key IN (_binary'display_name', _binary'author_note', _binary'enabled', _binary'description', _binary'source_page', _binary'owner_class', _binary'selection_level')) OR (rule_type = _binary'character.feature' AND field_key IN (_binary'display_name', _binary'author_note', _binary'enabled', _binary'description', _binary'source_page', _binary'owner', _binary'level', _binary'feature_kind', _binary'execution_mode', _binary'execution_algorithm')) OR (rule_type = _binary'character.feat' AND field_key IN (_binary'display_name', _binary'author_note', _binary'enabled', _binary'description', _binary'source_page', _binary'prerequisite', _binary'execution_mode', _binary'execution_algorithm')) OR (rule_type = _binary'character.proficiency' AND field_key IN (_binary'display_name', _binary'author_note', _binary'enabled', _binary'description', _binary'source_page', _binary'category', _binary'ability_key')) OR (rule_type = _binary'catalog.proficiency_set' AND field_key IN (_binary'display_name', _binary'author_note', _binary'enabled', _binary'category', _binary'minimum_enabled_members')) OR (rule_type IN (_binary'adventure.rest', _binary'adventure.check') AND field_key IN (_binary'display_name', _binary'description', _binary'source_page', _binary'algorithm', _binary'author_note', _binary'enabled')))) OR (target_kind = _binary'entry' AND collection_key IS NOT NULL AND module_key IS NOT NULL AND entry_key IS NOT NULL AND REGEXP_LIKE(CONVERT(module_key USING latin1), '^[a-z][a-z0-9_]{0,63}$', 'c') AND NOT REGEXP_LIKE(CONVERT(module_key USING latin1), '[^a-z0-9_]', 'c') AND REGEXP_LIKE(CONVERT(entry_key USING latin1), '^[a-z][a-z0-9_]{0,63}$', 'c') AND NOT REGEXP_LIKE(CONVERT(entry_key USING latin1), '[^a-z0-9_]', 'c') AND ((rule_type = _binary'character.class_progression' AND ((collection_key = _binary'levels' AND field_key IN (_binary'level', _binary'asi_available', _binary'author_note', _binary'enabled')) OR (collection_key IN (_binary'starting_proficiencies', _binary'multiclass_proficiencies') AND field_key IN (_binary'growth_grant', _binary'author_note', _binary'enabled')))) OR (rule_type = _binary'catalog.proficiency_set' AND collection_key = _binary'members' AND field_key IN (_binary'proficiency', _binary'author_note', _binary'enabled')))));

ALTER TABLE rule_schema2_advancement_change DROP CHECK ck_s2_src_advancement_change_6;
ALTER TABLE rule_schema2_advancement_change ADD CONSTRAINT ck_s2_src_advancement_change_6 CHECK ((operation = _binary'clear_field' AND field_key = _binary'author_note' AND text_value IS NULL AND integer_value IS NULL AND boolean_value IS NULL AND reference_module_key IS NULL AND growth_grant_kind IS NULL AND prerequisite_value IS NULL) OR (operation = _binary'set_enabled' AND field_key = _binary'enabled' AND boolean_value IS NOT NULL AND boolean_value IN (0, 1) AND text_value IS NULL AND integer_value IS NULL AND reference_module_key IS NULL AND growth_grant_kind IS NULL AND prerequisite_value IS NULL) OR (operation = _binary'set_field' AND ((text_value IS NOT NULL) + (integer_value IS NOT NULL) + (boolean_value IS NOT NULL) + (reference_module_key IS NOT NULL) + (growth_grant_kind IS NOT NULL) + (prerequisite_value IS NOT NULL)) = 1 AND ((field_key IN (_binary'display_name', _binary'description', _binary'author_note', _binary'proficiency_bonus_profile', _binary'maximum_profile', _binary'recovery_profile') AND text_value IS NOT NULL) OR (field_key = _binary'advancement_scope' AND text_value IS NOT NULL AND CAST(text_value AS BINARY) IN (_binary'STATISTICS_AND_RESOURCES_ONLY', _binary'CHARACTER_ADVANCEMENT')) OR (field_key = _binary'execution_mode' AND text_value IS NOT NULL AND CAST(text_value AS BINARY) IN (_binary'AUTOMATIC', _binary'DM_ADJUDICATION', _binary'BLOCKED') AND (rule_type <> _binary'character.resource' OR CAST(text_value AS BINARY) <> _binary'DM_ADJUDICATION')) OR (field_key = _binary'execution_algorithm' AND text_value IS NOT NULL AND CAST(text_value AS BINARY) IN (_binary'AUTOMATIC_RESOURCE_LIFECYCLE_V1', _binary'BOUNDED_SUBCLASS_SELECTION_V1', _binary'BOUNDED_FEATURE_SELECTION_V1', _binary'BOUNDED_DM_ADJUDICATION_V1', _binary'BLOCKED_ISSUE_8_V1', _binary'BLOCKED_SPELL_SYSTEM_V1', _binary'BLOCKED_DOWNSTREAM_SYSTEM_V1')) OR (field_key = _binary'feature_kind' AND text_value IS NOT NULL AND CAST(text_value AS BINARY) IN (_binary'FEATURE', _binary'OPTION')) OR (field_key = _binary'category' AND text_value IS NOT NULL AND CAST(text_value AS BINARY) IN (_binary'SKILL', _binary'ARMOR', _binary'WEAPON', _binary'TOOL') AND (rule_type <> _binary'character.proficiency' OR CAST(text_value AS BINARY) <> _binary'TOOL')) OR (field_key = _binary'algorithm' AND text_value IS NOT NULL AND ((rule_type = _binary'adventure.rest' AND CAST(text_value AS BINARY) = _binary'SRD_2014_REST_V1') OR (rule_type = _binary'adventure.check' AND CAST(text_value AS BINARY) = _binary'SRD_2014_ABILITY_CHECK_V1'))) OR (field_key = _binary'ability_key' AND text_value IS NOT NULL AND CAST(text_value AS BINARY) IN (_binary'ability.strength', _binary'ability.dexterity', _binary'ability.constitution', _binary'ability.intelligence', _binary'ability.wisdom', _binary'ability.charisma')) OR (field_key = _binary'source_page' AND integer_value IS NOT NULL AND ((rule_type = _binary'adventure.rest' AND integer_value = 87) OR (rule_type = _binary'adventure.check' AND integer_value = 77) OR (rule_type NOT IN (_binary'adventure.rest', _binary'adventure.check') AND integer_value BETWEEN 3 AND 74))) OR (field_key = _binary'hit_die_sides' AND integer_value IS NOT NULL AND integer_value IN (6, 8, 10, 12)) OR (field_key IN (_binary'supported_maximum_level', _binary'selection_level', _binary'level') AND integer_value IS NOT NULL AND integer_value BETWEEN 1 AND 20) OR (field_key = _binary'minimum_enabled_members' AND integer_value IS NOT NULL AND integer_value BETWEEN 1 AND 128) OR (field_key IN (_binary'owner_class', _binary'owner', _binary'proficiency') AND reference_module_key IS NOT NULL) OR (field_key = _binary'asi_available' AND boolean_value IS NOT NULL AND boolean_value IN (0, 1)) OR (field_key = _binary'growth_grant' AND growth_grant_kind IS NOT NULL) OR (field_key IN (_binary'multiclass_prerequisite', _binary'prerequisite') AND prerequisite_value IS NOT NULL AND prerequisite_value = 1))));

DELIMITER $$
CREATE TRIGGER rule_s2_check_insert BEFORE INSERT ON rule_schema2_check FOR EACH ROW
BEGIN
    DECLARE current_count BIGINT DEFAULT NULL;
    SELECT installation_count INTO current_count FROM rule_schema2_control WHERE control_id = 1 FOR UPDATE;
    IF current_count IS NULL OR NOT EXISTS (SELECT 1 FROM rule_schema2_artifact WHERE module_key = NEW.artifact_module_key AND release_version = NEW.release_version AND installation_sequence = current_count + 1)
        OR (SELECT COUNT(*) FROM rule_schema2_check WHERE artifact_module_key = NEW.artifact_module_key AND release_version = NEW.release_version) >= 256 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Check material requires current installation transaction';
    END IF;
END$$
CREATE TRIGGER rule_s2_check_update BEFORE UPDATE ON rule_schema2_check FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Immutable schema2 check material';
END$$
CREATE TRIGGER rule_s2_check_delete BEFORE DELETE ON rule_schema2_check FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Permanent schema2 check material';
END$$
DELIMITER ;
-- CHECKSUM-SCOPE-END

